"""Evidence wrapper: lets any agent decide, then rewrites each 'send' into a short business e-mail that
cites verified data (see evidence.py): up to 3 new claims, one question, refs set to the cited IDs.
Term sheets, accept and walk-away decisions are untouched; any failure keeps the delegate's decision."""

import logging
import re

from ..cost import OPS
from ..evidence import build_claims, load_package
from ..play import live_threads, standing

log = logging.getLogger("arena")

MAX_CLAIMS, MAX_WORDS = 3, 160
ID = re.compile(r"\b(?:idx|quote|sc|qn|po|fc|cost|news|doc|ctr|offer):[\w@.#-]*\w")
FIELDS = {"volume_per_year": "lift your allocation to {v} units per year"}


def _cited(events):
    """Every data ID our messages in a thread already cite (refs and body)."""
    return {i for m in events if m.get("from") == "buyer" for i in [*(m.get("refs") or []), *ID.findall(m.get("body") or "")]}


class EvidenceAgent:
    def __init__(self, delegate, data=None):
        self.delegate, self.data, self._pkg, self._loaded = delegate, data, None, False

    def __getattr__(self, name):  # e.g. `.chosen` of a wrapped router
        if name in ("delegate", "data", "_pkg", "_loaded"):
            raise AttributeError(name)
        return getattr(self.delegate, name)

    def decide(self, case, threads):
        decision = self.delegate.decide(case, threads)
        try:
            msg, sid = decision.get("message") or {}, decision.get("supplier_id")
            if msg.get("action") or sid not in threads or not threads[sid]:
                return decision
            if not self._loaded:
                self._loaded = True
                self._pkg = load_package(self.data)
            if self._pkg is None:
                return decision
            return {**decision, "message": self._rewrite(case, threads, sid, msg)}
        except Exception:
            log.exception("%s evidence: failed, keeping the delegate's message", case.get("case_id"))
            return decision

    def _rewrite(self, case, threads, sid, msg):
        events = threads[sid]
        _, terms = standing(events)
        price = terms.get("unit_price")
        used = set().union(*(_cited(e) for e in threads.values()))
        used = {i for i in used if not i.startswith("offer:")} | {i for i in _cited(events) if i.startswith("offer:")}
        claims = [c for c in build_claims(case, self._pkg, sid, price) if not used & set(c["ids"])]
        asks = []
        for m in case["buyer"].get("must_haves", []):
            cur = terms.get(m["field"])
            if cur is not None and not OPS[m["op"]](cur, m["value"]):
                what = FIELDS.get(m["field"]) or f"confirm {m['field'].replace('_', ' ')} {'of at least' if '>' in m['op'] else 'of at most'} {{v}}"
                asks.append(f"Could you {what.format(v=m['value'])}?")
                if m["field"] == "volume_per_year":
                    claims.sort(key=lambda c: c["kind"] != "fc")  # the forecast backs a volume ask (stable sort)
        rivals = [(standing(threads[o])[1].get("unit_price"), standing(threads[o])[0]) for o in live_threads(threads) if o != sid]
        rivals = [r for r in rivals if r[0] is not None and r[1] and price is not None and r[0] < price]
        if rivals and len(case.get("parts", [])) == 1 and not any(i.startswith("offer:") for i in _cited(events)):
            p, oid = min(rivals)
            claims.insert(0, {"kind": "offer", "ids": [oid], "strength": 90, "sentence": f"Another bidder's offer for this part stands at EUR {p:.2f} per unit ({oid})."})
        picked, ids = [], set()
        for c in claims:
            if c["kind"] != "calc" and len([x for x in picked if x["kind"] != "calc"]) < MAX_CLAIMS and not ids & set(c["ids"]):
                picked.append(c)
                ids |= set(c["ids"])
        calc = [c for c in claims if c["kind"] == "calc"]
        if calc and any(c["kind"] == "idx" for c in picked):
            picked.append(calc[0])
        picked.sort(key=lambda c: -c["strength"])
        theirs = [m for m in events if m.get("from") != "buyer"]
        last = theirs[-1]
        if not any(m.get("term_sheets") for m in theirs):
            asks.append("Could you please send us your quote?")
        elif sum(m.get("from") == "buyer" for m in events) == 0:
            asks.append("Could you send us a breakdown of the costs behind your price?")
        elif last.get("status") == "final_offer" or re.search(r"\b(limit|cap|allocation)", last.get("body") or "", re.I):
            asks.append("Could you explain the reason behind the limit you stated?")
        sheets = bool(msg.get("term_sheets"))
        company = re.search(r"for ([A-Z][\w&. -]+?) (?:with|from)", case.get("briefing", ""))
        sign = f"{company.group(1)}, Purchasing" if company else "Purchasing"
        subject = (msg.get("subject") or "Re: " + (last.get("subject") or case.get("title", "our enquiry")))[:300]

        def body(cs, qs):
            return "\n".join(["Dear Sir or Madam,", "", "thank you for your message." + (" Our proposed terms are in the term sheet of this message." if sheets else ""),
                              *[c["sentence"] for c in cs], *qs, "", "Best regards,", sign])

        qs = list(asks)
        while len(body(picked, qs).split()) > MAX_WORDS and (picked or len(qs) > 1):
            if picked:
                picked.pop()
            else:
                qs.pop()
        return {**msg, "subject": subject, "body": body(picked, qs), "refs": [i for c in picked for i in c["ids"]]}
"""SimplifyAgent: slim reciprocal agent. Anchor, steady matched concessions, RFQ round-robin.

Every choice among candidate sheets is priced with cost.total_cost, over the five parts of C:
1. price: anchor 0.80 x theirs, steady concessions matched to theirs;
2. uncovered need: contract length and volume are the options with the lowest C (never leave need uncovered);
3. payment, freight, lead time: each negotiable lever takes its lowest-C option, unless the supplier pinned it;
4. quality and other: ppm commitment likewise, plus a second sheet with an index clause for a higher price;
5. the supplier's health (strategic / bottleneck goals with a relationship cost): C charges for leaving the supplier below a
   sustainable margin, but the buyer cannot estimate its full cost (should-cost exists for about half the parts and can exceed
   the price), so cost.total_cost sees 0 and the mock does not price it. Safer rule there, UNTESTED against the real penalty:
   anchor 0.90 and only levers that cost the supplier nothing (contract length, volume); payment, freight, lead time and
   quality stay at the supplier's own terms.

Closing, must-have and pin helpers are shared with reciprocal.py."""

import math

from ..cost import RELATIONSHIP_GOALS, complete_offer, total_cost
from ..docs import standard_terms
from ..guard import satisfy_must_haves
from ..play import closing_move, latest, moves_left
from .reciprocal import (
    ANCHOR,
    ANCHOR_FLOOR,
    FRAC0,
    FRAC_MAX,
    FRAC_STEP,
    KEEP,
    MATCH,
    MIN_STEP,
    MOVING_MIN,
    _c_alt,
    _live,
    _mine,
    _pinned,
    _sup,
    _tick,
    _valid,
    case_c_open,
    closing_accept,
)

EASED_ANCHOR = 0.90
STALL = 0.01  # the supplier's best C fell by less than this (x C) across its last two replies: it has stalled
GAP = 0.05  # then our offer rises until it is at most this far (x their C) below theirs
FREE_LEVERS = ("contract_months", "volume_per_year")  # cost the supplier nothing in cash
LEVERS = ("contract_months", "volume_per_year", "payment_days", "incoterm", "lead_time_days", "ppm_commitment")


def _health_at_stake(case):
    """C charges for the supplier's margin (strategic / bottleneck goal with a price per margin point)."""
    b = case["buyer"]
    return b.get("category_goal") in RELATIONSHIP_GOALS and bool(b.get("relationship_eur_per_point"))


class SimplifyAgent:
    _c_open = math.inf  # set per decision; our offer never costs more than the closing rule would accept

    def decide(self, case, threads):
        if not _live(threads):  # nothing to answer
            return {"supplier_id": next(iter(threads), None), "message": {"action": {"type": "walk_away"}}}
        if accept := closing_accept(case, threads):
            return accept
        live = [s for s in _live(threads) if moves_left(case, threads[s]) >= 1]
        open_ = [s for s in live if latest(threads[s]).get("status") not in ("final_offer", "agreed")]
        if not open_:
            return closing_move(case, threads)

        def key(s):  # keep every thread moving: fewest messages first, then the cheapest
            ev = threads[s]
            c = min((c for c, _ in _valid(case, ev, standard_terms(ev), math.inf, musts=False)), default=math.inf)
            return len(_mine(ev)), c

        sid = min(open_, key=key)
        # cap: the opening and the best standing sheet of any other open thread
        others = [c for s in open_ if s != sid for c, _ in _valid(case, threads[s], standard_terms(threads[s]), math.inf)]
        self._c_open = min([case_c_open(case, threads), *others])
        events = threads[sid]
        std = standard_terms(events)
        valid = _valid(case, events, std, math.inf) or _valid(case, events, std, math.inf, musts=False)  # a must-have breach is fixed in our sheet
        if not valid:  # no priced sheet to answer: ask for one, give up after 3 asks
            if len(_mine(events)) >= 3:
                return {"supplier_id": sid, "message": {"action": {"type": "walk_away"}}}
            return {"supplier_id": sid, "message": {"subject": case.get("title", "Our enquiry"), "body": "Could you please send us your quote?"}}
        _, best = min(valid, key=lambda v: v[0])
        sheets = self._sheets(case, events, std, best["terms"])
        if not sheets:  # nothing new left to offer: close on the best sheet, or give up
            return closing_move(case, threads)
        return {
            "supplier_id": sid,
            "message": {
                "subject": case.get("title", "Our proposal"),
                "body": "Thank you for your offer. We have moved on our side; please see our updated terms.",
                "term_sheets": [{"terms": t} for t in sheets],
            },
        }

    @staticmethod
    def _their_move(events):
        """How far the supplier's best price fell in its last message (0 if it did not)."""
        ps = [min(s["terms"]["unit_price"] for s in m["term_sheets"] if s["terms"].get("unit_price") is not None)
              for m in _sup(events) if any(s["terms"].get("unit_price") is not None for s in m["term_sheets"])]
        return max(0.0, ps[-2] - ps[-1]) if len(ps) >= 2 else 0.0

    @staticmethod
    def _stalled(case, events, std):
        """We have opened and the supplier's best C fell by < STALL across its last two replies (3+ priced messages)."""
        cs = [min(total_cost(case, t["terms"], std) for t in m["term_sheets"] if t["terms"].get("unit_price") is not None)
              for m in _sup(events) if any(t["terms"].get("unit_price") is not None for t in m["term_sheets"])]
        return bool(_mine(events)) and len(cs) >= 3 and cs[-3] - cs[-1] < STALL * cs[-3]

    def _price(self, case, events, p):
        mine = [m["term_sheets"][0]["terms"]["unit_price"] for m in _mine(events) if m.get("term_sheets") and m["term_sheets"][0]["terms"].get("unit_price")]
        if not mine:
            cur = case["buyer"].get("current_unit_price") or p
            return max(ANCHOR_FLOOR * p, min((EASED_ANCHOR if _health_at_stake(case) else ANCHOR) * p, cur))  # anchor; never pay more than now unless forced
        frac = min(FRAC_MAX, FRAC0 + FRAC_STEP * len(mine))
        move = self._their_move(events)
        step = max(frac * (p - mine[-1]), MIN_STEP * p, _tick(p))
        if move > 0:  # they moved: answer in step, not beyond (a supplier that holds still gets the full step)
            step = max(MOVING_MIN * p, _tick(p), min(step, MATCH * move))
        top = p if moves_left(case, events) <= 2 else p * (1 - KEEP)
        return max(mine[-1], min(top, mine[-1] + step))

    def _sheets(self, case, events, std, theirs):
        p, pins = theirs["unit_price"], _pinned(events)
        base = {k: v for k, v in {**{f: std[f] for f in case["negotiable"] if f in std}, **theirs}.items() if v is not None}
        opts = case.get("term_options") or {}
        c_alt = _c_alt(case)
        sent = [m["term_sheets"] for m in _mine(events) if m.get("term_sheets")]
        seen = [s["terms"] for ss in sent for s in ss]

        def make(price, **over):
            over = {k: v for k, v in over.items() if k not in pins}
            return satisfy_must_haves(case, {**base, "unit_price": round(price, 2), **over}, std)

        def cost(t):
            return total_cost(case, t, std)

        def cap(t):  # hard floor: never offer a sheet that costs more than the alternative
            if (c := cost(t)) >= c_alt:
                slope = cost({**t, "unit_price": t["unit_price"] + 1}) - c
                if slope > 0:
                    t = {**t, "unit_price": round(t["unit_price"] - (c - c_alt) / slope - 0.01, 2)}
            return t

        def one(price):  # one sheet: for each negotiable lever the option with the lowest C (pinned ones stay theirs)
            over = {}
            for f in FREE_LEVERS if _health_at_stake(case) else LEVERS:
                options = [o for o in opts.get(f, []) if o] if f in case["negotiable"] and f not in pins else []
                if options:
                    over[f] = min(options, key=lambda o: cost(make(price, **over, **{f: o})))
            return cap(make(price, **over))

        price = self._price(case, events, p)
        main = one(price)
        floor = max((x["terms"]["unit_price"] for ss in sent for x in ss[:1] if x["terms"].get("unit_price")), default=0.0)
        while (main in seen or main["unit_price"] <= floor) and price < p:  # always a visible step, never a repeat, never above theirs
            price = min(p, price + _tick(p))
            new = one(price)
            if new == main:  # capped: the price cannot move
                break
            main = new
        if self._stalled(case, events, std):  # close the gap to <= GAP of their C, never past c_open
            f = lambda x: cost(one(x))
            target, lo, hi = (1 - GAP) * cost(theirs), main["unit_price"], p
            if f(hi) >= target:  # smallest price that reaches the target
                for _ in range(30):
                    mid = (lo + hi) / 2
                    lo, hi = (lo, mid) if f(mid) >= target else (mid, hi)
            if f(hi) > self._c_open:  # largest price that stays within c_open
                lo = main["unit_price"]
                for _ in range(30):
                    mid = (lo + hi) / 2
                    lo, hi = (mid, hi) if f(mid) <= self._c_open else (lo, mid)
                hi = lo
            hi = round(hi, 2)
            while hi > main["unit_price"] and f(hi) > self._c_open:  # rounding must not pass c_open
                hi = round(hi - 0.01, 2)
            if hi > main["unit_price"]:
                main = one(hi)
        if main in seen:
            return []
        out, variants = [main], []
        # the index clause is security for them, not cash: offer it at the price where our C stays just below main's
        clauses = (c for c in opts.get("index_clause", []) if c) if "index_clause" in case["negotiable"] and "index_clause" not in pins else []
        # the clause (deadband) with the lowest C at main's price is tried first: equal prices after the cap must not pick deadband 0
        for clause in sorted(clauses, key=lambda c: cost(make(main["unit_price"], index_clause=c, **{f: main[f] for f in LEVERS if f in main}))):
            t = make(main["unit_price"], index_clause=clause, **{f: main[f] for f in LEVERS if f in main})
            slope = cost({**t, "unit_price": t["unit_price"] + 1}) - cost(t)
            if t["index_clause"] == clause != main.get("index_clause") and slope > 0:
                price = round(max(0.75 * p, min(p, t["unit_price"] - (cost(t) - cost(main)) / slope - 0.01)), 2)  # no lowball
                v = cap({**t, "unit_price": price})
                if v not in seen and cost(v) < cost(main):
                    variants.append(v)
        if variants:
            out.append(max(variants, key=lambda v: v["unit_price"]))  # max keeps the first (lowest-C clause) on ties
        return [complete_offer(case, t) for t in out]
"""Score agents against the real-like local arena: every case x seed, no API, no credits.

    python -m arena_kit.evaluate --agents guarded_rational,confident_router --set dev --seeds 5

--set dev|test: the generated cases (gen_cases.py; tune on dev, score on test once); real: the 10 hosted
real practice cases, plus a comparison with the scores the same agents really got (sim_cases/real_runs).
It starts arena-sim itself on a free local port (one server per seed, the suppliers' draws follow the seed),
plays with the kit's own client and agents, and stops the servers at the end. It refuses a non-local
ARENA_URL and the `llm` agent (it would call a model API). Reads local files only.
"""

import argparse
import json
import os
import socket
import statistics as st
import threading
import time
from collections import defaultdict
from pathlib import Path
from urllib.parse import urlparse

from .cli import AGENTS, agent_factory
from .client import ArenaClient
from .play import RemoteTable, hosted, play_all
from .sim import CASES, load_cases
from .sim_real import SimReal

LOCAL = {"127.0.0.1", "localhost", "::1"}
DEFAULT_DATA = Path.home() / "Documents/Codex/negotiation-arena-kit/data"


def check_local():
    url = os.environ.get("ARENA_URL")
    if url and urlparse(url).hostname not in LOCAL:
        raise SystemExit(f"refusing to run: ARENA_URL={url} is not local; evaluate only talks to its own simulator")


class Server:
    """arena-sim with the real-like supplier, on a free local port, in a thread."""

    def __init__(self, sim):
        import uvicorn

        from .sim import create_app

        with socket.socket() as s:
            s.bind(("127.0.0.1", 0))
            self.port = s.getsockname()[1]
        self.server = uvicorn.Server(
            uvicorn.Config(create_app(sim), host="127.0.0.1", port=self.port, log_level="error")
        )
        self.thread = threading.Thread(target=self.server.run, daemon=True)

    def __enter__(self):
        self.thread.start()
        for _ in range(200):
            if self.server.started:
                return f"http://127.0.0.1:{self.port}"
            time.sleep(0.05)
        raise RuntimeError("the simulator did not start")

    def __exit__(self, *exc):
        self.server.should_exit = True
        self.thread.join(10)


def case_folder(which):
    return {"dev": CASES / "gen_dev", "test": CASES / "gen_test", "real": CASES / "real"}[which]


def play_set(agents, which, seeds, data, parallel):
    """(cases, {agent: {(case_id, seed): score}}, {agent: [(case_id, seed) of crashed games]})"""
    cases = load_cases(case_folder(which))
    ids = [c["case_id"] for c in hosted(list(cases.values()))]
    facts = {}
    if data and (Path(data) / "facts.json").is_file():
        from .data import DataPackage

        facts = DataPackage(data).facts
    else:
        print(
            f"WARNING: no data package at {data!r} (--data): cited IDs cannot be verified and evidence agents degrade"
        )
    out = {a: {} for a in agents}
    crashed = {a: [] for a in agents}
    for seed in range(seeds):
        sim = SimReal(cases, facts, "sim", no_clock=True, seed=seed)  # no 60 s rule: agents here are fast
        sim.max_calls = 10**9  # and no 10-calls-per-second limit: one machine plays many games at once
        with Server(sim) as url:
            for name in agents:
                key = ArenaClient(url, api_key="x").register(f"{name}-{seed}", "sim")["api_key"]
                client = ArenaClient(url, key, rate=1000)
                done = play_all(lambda client=client: RemoteTable(client), ids, agent_factory(name, data), parallel)
                for cid, r in done.items():
                    if isinstance(r, dict):
                        out[name][(cid, seed)] = r.get("score") or 0.0
                    else:  # a crashed game is not a score of 0: it is left out of the means and counted
                        crashed[name].append((cid, seed))
                        print(f"  CRASHED {name} {cid} seed {seed}: {r!r}")
    return cases, out, crashed


def mean(xs):
    return st.mean(xs) if xs else float("nan")


def report(cases, scores, crashed):
    print(f"\n{'agent':20} {'mean':>6} {'deal>0':>7} {'crashed':>8} {'worst case (mean over seeds)':>34}")
    for a, res in scores.items():
        per_case = defaultdict(list)
        for (cid, _), v in res.items():
            per_case[cid].append(v)
        worst = min(per_case, key=lambda c: mean(per_case[c]))
        allv = list(res.values())
        print(
            f"{a:20} {mean(allv):6.3f} {mean([v > 0 for v in allv]):7.2f} {len(crashed[a]):8d} "
            f"{worst:>22} {mean(per_case[worst]):6.3f}"
        )
    types = sorted({c["type"] for c in cases.values()})
    print(f"\n{'mean score by case type':24}" + "".join(f"{a[:14]:>16}" for a in scores))
    for t in types:
        row = []
        for res in scores.values():
            row.append(mean([v for (cid, _), v in res.items() if cases[cid]["type"] == t]))
        print(f"{t:24}" + "".join(f"{x:16.3f}" for x in row))


def real_scores():
    """The scores the agents really got on the practice arena: {(agent, 'case:Pxx'): score}."""
    out = {}
    for f in sorted((CASES / "real_runs").glob("*_P*.json")):
        d = json.loads(f.read_text(encoding="utf-8"))
        out[(d["agent"], f"case:{d['case']}")] = d["result"]["score"]
    return out


def compare(cases, scores):
    real = real_scores()
    agents = [a for a in scores if any(k[0] == a for k in real)]
    rows = []
    for a in agents:
        for cid in sorted({c for (x, c) in real if x == a}):
            m = mean([v for (c, _), v in scores[a].items() if c == cid])
            rows.append((a, cid, real[(a, cid)], m))
    print("\nMOCK vs REAL (the same agents, the same 10 hosted cases)")
    print("IN-SAMPLE: the supplier profile was fitted on these same real runs, so this checks the fit, not the mock's")
    print("           power to predict; it says nothing about cases or agents the profile never saw.")
    print(f"{'agent':20} {'real mean':>9} {'mock mean':>9}")
    for a in agents:
        r = [x[2] for x in rows if x[0] == a]
        m = [x[3] for x in rows if x[0] == a]
        print(f"{a:20} {mean(r):9.3f} {mean(m):9.3f}")
    if len(rows) > 2:
        r_all = st.correlation([x[2] for x in rows], [x[3] for x in rows])
        print(f"in-sample correlation over {len(rows)} (agent, case) pairs: {r_all:.2f}")
        by_case = defaultdict(list)
        for _, cid, r, m in rows:
            by_case[cid].append((r, m))
        cm = {c: (mean([r for r, _ in v]), mean([m for _, m in v])) for c, v in by_case.items()}
        if len(cm) > 2:
            print(f"in-sample correlation over {len(cm)} case means (does the mock find the same cases hard?): "
                  f"{st.correlation([v[0] for v in cm.values()], [v[1] for v in cm.values()]):.2f}")  # fmt: skip
    print("biggest mismatches (agent, case, real, mock):")
    for a, cid, r, m in sorted(rows, key=lambda x: -abs(x[2] - x[3]))[:8]:
        print(f"  {a:20} {cid:10} {r:6.3f} {m:6.3f}")


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    ap.add_argument("--agents", default="guarded_rational,confident_router")
    ap.add_argument("--set", choices=["dev", "test", "real"], default="dev")
    ap.add_argument("--seeds", type=int, default=5)
    ap.add_argument("--data", default=os.environ.get("ARENA_DATA") or str(DEFAULT_DATA))
    ap.add_argument("--parallel", type=int, default=8)
    a = ap.parse_args(argv)
    check_local()
    agents = a.agents.split(",")
    bad = [x for x in agents if x not in AGENTS or x == "llm"]
    if bad:
        raise SystemExit(
            f"unknown or not allowed (llm calls a model API): {bad}; choose from {[x for x in AGENTS if x != 'llm']}"
        )
    cases, scores, crashed = play_set(agents, a.set, a.seeds, a.data, a.parallel)
    report({k: v for k, v in cases.items() if v.get("hosted", True)}, scores, crashed)
    if a.set == "real":
        compare(cases, scores)


if __name__ == "__main__":
    main()
